+                snippet = null;
+                contents = null;
+            }
+            if (snippet != null) {
+                finalizeSnippet(snippet, contents.toString(), defaultSubstitutions, substitutions);
+                contents = null;
+                snippet = null;
+                substitutions = new ArrayList<>();
