+            assertEquals("numWords= " + numWords, sb.toString(), chunks.get(chunkIndex));
+
+            reachedEnd = end == numWords;
+            start += newWordsPerWindow;
+            chunkIndex++;
+        }
+
+        assertEquals("numWords= " + numWords, chunks.size(), chunkIndex);
+    }
